mapper.select:
SELECT 
FROM idp_enterprise_application_authorization

    AND id = #{id}

        AND id IN

            #{item}


    AND idp_type = #{idpType}
    AND bind_mode = #{bindMode}

        AND idp_application_code = #{idpApplicationCode}

    AND enterprise_id = #{enterpriseId}

        AND installed_application_id = #{installedApplicationId}


        AND authorization_status = #{authorizationStatus}

    AND (delete_flag = 0 OR delete_flag IS NULL)

ORDER BY id DESC
